package com.godjiismp.skills;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.IntegerArgumentType;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.fabricmc.fabric.api.networking.v1.PayloadTypeRegistry;
import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;
import net.minecraft.commands.CommandBuildContext;import net.minecraft.commands.CommandSourceStack;import net.minecraft.commands.Commands;import net.minecraft.commands.arguments.EntityArgument;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;

public final class Skills {
 private Skills(){}
 public static void init(){SkillsConfig.load();SkillHooks.init();PayloadTypeRegistry.playS2C().register(SkillPayload.TYPE,SkillPayload.CODEC);PayloadTypeRegistry.playS2C().register(SkillOpenPayload.TYPE,SkillOpenPayload.CODEC);PayloadTypeRegistry.playC2S().register(SkillUpgradePayload.TYPE,SkillUpgradePayload.CODEC);PayloadTypeRegistry.playC2S().register(SkillRequestPayload.TYPE,SkillRequestPayload.CODEC);CommandRegistrationCallback.EVENT.register(Skills::register);ServerPlayNetworking.registerGlobalReceiver(SkillUpgradePayload.TYPE,(payload,ctx)->ctx.server().execute(()->upgrade(ctx.player(),payload.line())));ServerPlayNetworking.registerGlobalReceiver(SkillRequestPayload.TYPE,(payload,ctx)->ctx.server().execute(()->send(ctx.player(),true)));}
 private static void register(CommandDispatcher<CommandSourceStack>d,CommandBuildContext c,Commands.CommandSelection e){d.register(Commands.literal("skills").executes(ctx->{ServerPlayer p=ctx.getSource().getPlayerOrException();send(p,true);return 1;}).then(Commands.literal("give").requires(s->s.hasPermission(2)).then(Commands.argument("player",EntityArgument.player()).then(Commands.argument("points",IntegerArgumentType.integer(1,10000)).executes(ctx->{ServerPlayer p=EntityArgument.getPlayer(ctx,"player");awardPoints(p,IntegerArgumentType.getInteger(ctx,"points"));ctx.getSource().sendSuccess(()->Component.literal("Skill points granted."),true);return 1;})))).then(Commands.literal("reset").executes(ctx->{ServerPlayer p=ctx.getSource().getPlayerOrException();reset(p);return 1;})));}
 public static void awardPoints(ServerPlayer player,int amount){if(amount<=0)return;SkillData d=SkillData.get(player.getServer());SkillData.Entry e=d.entry(player.getUUID());e.points=(int)Math.min(Integer.MAX_VALUE,(long)e.points+amount);d.changed();player.sendSystemMessage(Component.literal("You earned "+amount+" skill point"+(amount==1?"":"s")+"."));send(player,false);}
 private static void upgrade(ServerPlayer p,int line){if(line<0||line>=6)return;SkillData d=SkillData.get(p.getServer());SkillData.Entry e=d.entry(p.getUUID());int level=e.levels[line];if(level>=10){p.sendSystemMessage(Component.literal("This skill line is already maxed."));return;}int cost=SkillsConfig.costs[level];if(e.points<cost){p.sendSystemMessage(Component.literal("Not enough skill points."));send(p,false);return;}e.points-=cost;e.spent+=cost;e.levels[line]++;d.changed();send(p,false);p.sendSystemMessage(Component.literal("Skill upgraded: "+SkillsConfig.LINES[line]+" Lv "+e.levels[line]+"."));}
 private static void reset(ServerPlayer p){SkillData d=SkillData.get(p.getServer());SkillData.Entry e=d.entry(p.getUUID());long now=System.currentTimeMillis();long wait=SkillsConfig.resetCooldownHours*3_600_000L;if(e.resetAt>now){p.sendSystemMessage(Component.literal("Skill reset is on cooldown."));return;}if(SkillsConfig.resetCost>0&&!com.godjiismp.Money.take(p.getServer(),p.getUUID(),SkillsConfig.resetCost)){p.sendSystemMessage(Component.literal("Not enough money to reset skills."));return;}e.points=(int)Math.min(Integer.MAX_VALUE,(long)e.points+e.spent);e.spent=0;java.util.Arrays.fill(e.levels,0);e.resetAt=now+wait;d.changed();send(p,false);p.sendSystemMessage(Component.literal("Skills reset. Spent skill points were refunded."));}
 public static int level(ServerPlayer p,int line){return SkillData.get(p.getServer()).entry(p.getUUID()).levels[line];}
 private static void send(ServerPlayer p,boolean open){if(open&&ServerPlayNetworking.canSend(p,SkillOpenPayload.TYPE))ServerPlayNetworking.send(p,new SkillOpenPayload());if(ServerPlayNetworking.canSend(p,SkillPayload.TYPE)){SkillData.Entry e=SkillData.get(p.getServer()).entry(p.getUUID());String[][] perks=new String[6][10];for(int l=0;l<6;l++)for(int i=0;i<10;i++)perks[l][i]="Lv "+(i+1)+": "+SkillsConfig.perkNames[l][i]+"\n"+SkillsConfig.perkDescriptions[l][i];ServerPlayNetworking.send(p,new SkillPayload(e.points,e.levels.clone(),SkillsConfig.costs.clone(),perks));}}
}

